# R-55 (the review 14:15): no English in a report to the owner — the old rows too
import re as _re
HEB = [(r'\bJS\b', 'זמן הסקריפט'), (r'(?<=\d) ?MB\b', ' מגה-בייט'), (r'\bMB\b', 'מגה-בייט'), (r'(?<=\d) ?ms\b', ' אלפיות שנייה'), (r'\bms\b', 'אלפיות שנייה'), (r'(?<=\d) ?px\b', ' פיקסלים'),
       (r' ?\(TR/CM/FW\)', ''), (r'\bcensus3?\b', 'ספירת המצוירים מלמעלה'), (r'\berrtour\b', 'סיור השגיאות'), (r'\bgpu_who\b', 'מדידת הכרטיס הגרפי'), (r'\(הצעה A\)', '(הצעה א׳)'), (r'\bICON A5\b', 'המטוס הדו-חי A5')]
def heb(o):
    if isinstance(o, str):
        if o.startswith('http'): return o
        for a_, b_ in HEB: o = _re.sub(a_, b_, o)
        return o
    if isinstance(o, list): return [heb(x) for x in o]
    if isinstance(o, dict): return {k: (v if k == 'links' else heb(v)) for k, v in o.items()}
    return o
